export interface RouteBodies {
  'admin.team.store': TeamInput
  'login.store': LoginInput
  'posts.comments.store': CommentInput
  'posts.store': PostInput
  'posts.update': PostInput
  'register.store': RegisterInput
  'settings.preferences.update': PreferencesInput
  'settings.profile.update': ProfileInput
  'uploads.store': IFormFile
}

export interface TeamInput {
  name: string | null
  email: string | null
  password: string | null
}

export interface LoginInput {
  email: string
  password: string
  remember: boolean
}

export interface CommentInput {
  body: string
}

export interface PostInput {
  title: string
  body: string
  coverUrl: string | null
  topics: string[] | null
  isPublished: boolean | null
}

export interface RegisterInput {
  name: string
  email: string
  password: string
  passwordConfirmation: string
}

export interface PreferencesInput {
  theme: string | null
  emailOnComment: boolean
  emailOnLike: boolean
  weeklyDigest: boolean
  dailyRecommendationDigest: boolean
  timeZoneId: string
}

export interface ProfileInput {
  displayName: string | null
  bio: string | null
  avatarUploadId: string | null
  removeAvatar: boolean
}

export interface IFormFile {
  contentType: string
  contentDisposition: string
  headers: Record<string, string[]>
  length: number
  name: string
  fileName: string
}

